<?php if($screen==='student-reservations'): ?><script>
(function(){var grid=document.getElementById('availability-grid');if(!grid)return;var date=document.getElementById('booking-date'),slot=document.getElementById('booking-slot'),people=document.getElementById('booking-people'),message=document.getElementById('availability-message');var api=grid.dataset.api;
function addHidden(form,name,value){var input=document.createElement('input');input.type='hidden';input.name=name;input.value=value;form.appendChild(input);}
async function refresh(){if(!date.value||!slot.value){grid.replaceChildren();message.textContent='Choose a date and time slot to see the tables.';return;}message.textContent='Checking table availability…';try{var query=new URLSearchParams({date:date.value,slot:slot.value,people:people.value});var response=await fetch(api+'?'+query.toString(),{headers:{'Accept':'application/json'}});var result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'Availability could not be loaded.');message.textContent='Table availability for '+date.value+' · '+result.tables.filter(function(t){return t.availability==='available';}).length+' tables available';grid.replaceChildren();result.tables.forEach(function(table){var card=document.createElement('div');card.className='rounded-xl border p-4 '+(table.availability==='available'?'border-emerald-300 bg-emerald-50':(table.availability==='booked'?'border-red-200 bg-red-50':'border-slate-200 bg-slate-100'));var title=document.createElement('strong');title.textContent=table.table_number;var cap=document.createElement('div');cap.className='text-sm text-slate-600 mt-1';cap.textContent='Capacity '+table.capacity;var state=document.createElement('div');state.className='text-xs font-semibold uppercase tracking-wide mt-2';state.textContent=table.availability.replace('_',' ');card.append(title,cap,state);if(table.availability==='available'){var form=document.createElement('form');form.method='post';form.action=grid.dataset.action;form.className='mt-3';addHidden(form,'csrf_token',grid.dataset.csrf);addHidden(form,'task','reserve');addHidden(form,'table_id',table.id);addHidden(form,'reservation_date',date.value);addHidden(form,'slot_id',slot.value);addHidden(form,'party_size',people.value);var button=document.createElement('button');button.type='submit';button.className='btn btn-primary btn-sm w-full';button.textContent='Reserve table';form.appendChild(button);card.appendChild(form);}grid.appendChild(card);});if(!result.tables.length)message.textContent='No tables have been added by the canteen yet.';}catch(err){message.textContent=err.message;}}
[date,slot,people].forEach(function(el){el.addEventListener('change',refresh);});refresh();})();
</script><?php endif; ?>
<?php if($screen==='order'): ?><script>
(function(){var box=document.getElementById('order-status-poller');if(!box)return;async function refresh(){try{var q=new URLSearchParams({id:box.dataset.orderId});var response=await fetch(box.dataset.api+'?'+q.toString(),{headers:{'Accept':'application/json'}});var result=await response.json();var order=result.data&&result.data.data;if(order&&order.status!==box.dataset.currentStatus)window.location.reload();}catch(e){}}window.setInterval(refresh,10000);})();
</script><?php endif; ?>
<?php if($screen==='admin-dashboard'): ?><script>
(function(){var canvas=document.getElementById('sales-chart');if(!canvas||typeof Chart==='undefined')return;var labels=<?= json_encode($salesChart['labels']??[],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;var values=<?= json_encode($salesChart['values']??[],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;new Chart(canvas,{type:'line',data:{labels:labels,datasets:[{label:'Sales (₹)',data:values,borderColor:'#4f46e5',backgroundColor:'rgba(99,102,241,.12)',fill:true,tension:.35,pointRadius:3}]},options:{maintainAspectRatio:false,responsive:true,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{callback:function(value){return '₹'+value;}}}}}});})();
</script><?php endif; ?>
